/**
 * Represents a scholarship within the school, containing details about the scholarship's name, description, discount percentage, and status.
 * This entity is used to manage scholarships that can be applied to student enrollments, allowing for discounts on tuition fees based on the scholarship's discount percentage.
 */
export interface Scholarship {
    /**
     * Required - Unique identifier for the scholarship, generated by backend
     */
    id: string;

    /**
     * Required - Name of the scholarship
     * Example: "Beca de excelencia académica"
     */
    name: string;

    /**
     * Required - Description of the scholarship
     * Example: "Beca otorgada a estudiantes con un rendimiento académico sobresaliente, que cubre el 50% de la colegiatura."
     */
    description: string;

    /**
     * Required - Discount percentage provided by the scholarship
     * This field represents the percentage of discount that the scholarship provides on tuition fees. For example, a value of 50 means a 50% discount on tuition fees for students who are awarded this scholarship.
     */
    discountPercentage: number;

    /**
     * Required - Indicates if the scholarship is active
     */
    status: boolean;
}
